"use strict";(self.webpackChunktranzila_payment_for_woocommerce_pos_doc=self.webpackChunktranzila_payment_for_woocommerce_pos_doc||[]).push([[135],{5953(e,t,n){n.r(t),n.d(t,{_pageData:()=>o,default:()=>i});var a=n(641);const o=JSON.parse('{"path":"/tranzila-payment/faq-notes.html","title":"FAQ & Troubleshooting","lang":"en-US","frontmatter":{},"git":{},"filePathRelative":"tranzila-payment/faq-notes.md"}'),r={name:"faq-notes.md"},i=(0,n(6262).A)(r,[["render",function(e,t,n,o,r,i){return(0,a.uX)(),(0,a.CE)("div",null,[...t[0]||(t[0]=[(0,a.Fv)('<h1 id="faq-troubleshooting" tabindex="-1"><a class="header-anchor" href="#faq-troubleshooting"><span>FAQ &amp; Troubleshooting</span></a></h1><p>Find answers to frequently asked questions and learn how to resolve common configuration and connection issues with the Tranzila Payment for WooCommerce POS addon.</p><hr><h2 id="_1-gateway-settings-visibility" tabindex="-1"><a class="header-anchor" href="#_1-gateway-settings-visibility"><span>1. Gateway &amp; Settings Visibility</span></a></h2><h3 id="why-are-the-tranzila-settings-not-visible-when-editing-my-pos-outlet" tabindex="-1"><a class="header-anchor" href="#why-are-the-tranzila-settings-not-visible-when-editing-my-pos-outlet"><span>Why are the Tranzila settings not visible when editing my POS Outlet?</span></a></h3><ul><li><strong>Cause 1: Payment Method Disabled:</strong> The global POS gateway is not activated. <ul><li><strong>Solution:</strong> Navigate to <strong>Point of Sale → Settings → Payment</strong> and verify that the &quot;Tranzila Terminal&quot; status toggle is set to <strong>Enable</strong>.</li></ul></li><li><strong>Cause 2: Payment option unchecked:</strong> The outlet has not enabled Tranzila as a valid payment option. <ul><li><strong>Solution:</strong> Scroll to the <strong>Payment Options</strong> section on the Outlet Edit page and make sure the checkbox next to <strong>Tranzila Terminal</strong> is checked. The settings fields will dynamically expand once selected.</li></ul></li></ul><hr><h2 id="_2-configuration-api-failures" tabindex="-1"><a class="header-anchor" href="#_2-configuration-api-failures"><span>2. Configuration &amp; API Failures</span></a></h2><h3 id="i-saved-a-new-pos-id-and-supplier-name-but-the-checkout-terminal-still-uses-the-old-credentials" tabindex="-1"><a class="header-anchor" href="#i-saved-a-new-pos-id-and-supplier-name-but-the-checkout-terminal-still-uses-the-old-credentials"><span>I saved a new POS ID and Supplier Name, but the checkout terminal still uses the old credentials.</span></a></h3><ul><li><strong>Cause: Cash Register Caching:</strong> WooCommerce POS caches outlet user data in the browser&#39;s local storage to optimize checkout loading speeds.</li><li><strong>Solution:</strong><ol><li>Log out of the POS register dashboard.</li><li>Perform a hard refresh in your browser (<strong>Ctrl + F5</strong> on Windows/Linux, or <strong>Cmd + Shift + R</strong> on macOS).</li><li>Log back in to force the client to download the updated outlet postmeta keys.</li></ol></li></ul><h3 id="the-terminal-returns-an-api-connection-error-during-checkout" tabindex="-1"><a class="header-anchor" href="#the-terminal-returns-an-api-connection-error-during-checkout"><span>The terminal returns an API connection error during checkout.</span></a></h3><ul><li><strong>Cause 1: Credentials Mismatch:</strong> The POS ID or Supplier Name is incorrect. <ul><li><strong>Solution:</strong> Verify that your Tranzila merchant key matches your physical hardware configuration exactly.</li></ul></li><li><strong>Cause 2: Transaction Mode Mismatch:</strong> Sandbox credentials are being used in Production Mode, or vice versa. <ul><li><strong>Solution:</strong> Ensure your <strong>Transaction Mode</strong> matches your active credential tier. Sandbox testing requires the standard <code>tranzilap</code> test supplier.</li></ul></li><li><strong>Cause 3: Internet Connection:</strong> The POS server or local terminal lacks external internet access to communicate with Tranzila servers. <ul><li><strong>Solution:</strong> Check the network connectivity on both the POS server and the terminal device.</li></ul></li></ul><hr><h2 id="_3-operations-auditing" tabindex="-1"><a class="header-anchor" href="#_3-operations-auditing"><span>3. Operations &amp; Auditing</span></a></h2><h3 id="where-can-i-find-the-tranzila-transaction-authentication-codes-for-a-pos-order" tabindex="-1"><a class="header-anchor" href="#where-can-i-find-the-tranzila-transaction-authentication-codes-for-a-pos-order"><span>Where can I find the Tranzila transaction authentication codes for a POS order?</span></a></h3><ul><li><strong>Answer:</strong> Transaction metadata is saved directly to the WordPress WooCommerce order records. <ul><li>Navigate to <strong>WooCommerce → Orders</strong> and click on the specific order.</li><li>Scroll down to the <strong>Custom Fields</strong> or order notes section to view the saved Tranzila transaction reference ID, auth codes, credit type, and processing response codes.</li></ul></li></ul><blockquote><p>[!CAUTION] <strong>Production Key Safety:</strong> Never share your active production POS ID, Supplier account passwords, or API keys in public forums or unencrypted support tickets. Keep credentials secure to prevent fraudulent transactions or chargebacks.</p></blockquote>',17)])])}]])}}]);